// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title CertificateRegistry
/// @notice Spec Phase 4 / Level 1 verification, full module (sections
/// 22-31). Keyed by certificateId (not by hash - a real change from this
/// contract's earlier hash-keyed version), so a lookup can compare a
/// freshly-recomputed candidate hash against whatever was actually
/// registered (spec section 30's "Blockchain Query -> Stored Hash ->
/// Compare"), and so a correction never mutates history: registering the
/// same certificateId again appends a new, independent version rather
/// than overwriting one (spec section 23: "Institutions must NOT be able
/// to modify an already finalized Blockchain record. If correction is
/// required, create a new version/revocation record"). Every version
/// ever written stays readable forever via getCertificateVersion; only
/// the latest one is authoritative for verifyCertificate/getCertificate.
///
/// Does NOT store certificate files or personal data (spec section 25) -
/// only a hash, a few identifiers, and an IPFS CID pointing at the
/// (separately encrypted, see certify-backend's ipfs_service.py) document.
///
/// Access control (spec section 28's "Only authorized institution wallets
/// should be able to register their certificates"): a fixed owner address
/// (set at deploy time, immutable) maintains an authorized-issuer
/// allowlist. Registering and revoking both require msg.sender to be on
/// it; verifying and reading are open to anyone, no wallet needed - the
/// whole point of an on-chain registry is that anyone can check it.
contract CertificateRegistry {
    struct Certificate {
        bytes32 certificateHash; // SHA-256 of the canonical certificate metadata JSON - see blockchain_service.py
        string institutionId; // this project's own Institution._id (Mongo ObjectId as string), not an on-chain identity
        string certificateId; // the institution's own certificate/serial number
        string ipfsCid; // points at the encrypted certificate file - see spec section 26
        uint256 issuedAt;
        bool revoked;
        uint256 version; // 0-indexed - matches this Certificate's position in _versions[certificateId]
    }

    address public immutable owner;
    mapping(address => bool) public authorizedIssuers;
    mapping(string => Certificate[]) private _versions;

    event IssuerAuthorized(address indexed issuer);
    event IssuerRevoked(address indexed issuer);
    event CertificateRegistered(
        string indexed certificateId,
        bytes32 certificateHash,
        string institutionId,
        string ipfsCid,
        uint256 version,
        uint256 issuedAt
    );
    event CertificateRevoked(string indexed certificateId, uint256 version, uint256 revokedAt);

    error NotOwner();
    error NotAuthorizedIssuer();
    error NoSuchCertificate(string certificateId);
    error AlreadyRevoked(string certificateId);

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyAuthorizedIssuer() {
        if (!authorizedIssuers[msg.sender]) revert NotAuthorizedIssuer();
        _;
    }

    constructor() {
        owner = msg.sender;
        authorizedIssuers[msg.sender] = true; // the deployer (this project's own backend wallet) starts authorized
        emit IssuerAuthorized(msg.sender);
    }

    function authorizeIssuer(address issuer) external onlyOwner {
        authorizedIssuers[issuer] = true;
        emit IssuerAuthorized(issuer);
    }

    function revokeIssuer(address issuer) external onlyOwner {
        authorizedIssuers[issuer] = false;
        emit IssuerRevoked(issuer);
    }

    /// @notice Appends a new version for certificateId. Never reverts on
    /// "already exists" - that's the whole point (a correction creates a
    /// new version instead of failing or overwriting); the OLD version
    /// stays exactly as it was, forever, at its own version index.
    function registerCertificate(
        string calldata certificateId,
        bytes32 certificateHash,
        string calldata institutionId,
        string calldata ipfsCid
    ) external onlyAuthorizedIssuer returns (uint256 version) {
        version = _versions[certificateId].length;
        _versions[certificateId].push(
            Certificate({
                certificateHash: certificateHash,
                institutionId: institutionId,
                certificateId: certificateId,
                ipfsCid: ipfsCid,
                issuedAt: block.timestamp,
                revoked: false,
                version: version
            })
        );
        emit CertificateRegistered(certificateId, certificateHash, institutionId, ipfsCid, version, block.timestamp);
    }

    /// @notice Marks the LATEST version revoked - itself just another
    /// immutable append (a fresh Certificate entry copied from the latest
    /// one with revoked=true), not a mutation of the existing entry, so
    /// the pre-revocation version is still readable at its own index.
    function revokeCertificate(string calldata certificateId) external onlyAuthorizedIssuer {
        Certificate[] storage versions = _versions[certificateId];
        if (versions.length == 0) revert NoSuchCertificate(certificateId);
        Certificate memory latest = versions[versions.length - 1];
        if (latest.revoked) revert AlreadyRevoked(certificateId);

        uint256 newVersion = versions.length;
        versions.push(
            Certificate({
                certificateHash: latest.certificateHash,
                institutionId: latest.institutionId,
                certificateId: certificateId,
                ipfsCid: latest.ipfsCid,
                issuedAt: latest.issuedAt,
                revoked: true,
                version: newVersion
            })
        );
        emit CertificateRevoked(certificateId, newVersion, block.timestamp);
    }

    function isCertificateRegistered(string calldata certificateId) external view returns (bool) {
        return _versions[certificateId].length > 0;
    }

    /// @notice The latest version - what verifyCertificate compares
    /// against and what a human-facing "current status" view should show.
    function getCertificate(string calldata certificateId) external view returns (Certificate memory) {
        Certificate[] storage versions = _versions[certificateId];
        if (versions.length == 0) revert NoSuchCertificate(certificateId);
        return versions[versions.length - 1];
    }

    /// @notice Full history - every version ever registered/revoked for
    /// this certificateId, oldest first. Read-only audit trail; nothing
    /// here can be edited or removed once written.
    function getCertificateHistory(string calldata certificateId) external view returns (Certificate[] memory) {
        return _versions[certificateId];
    }

    /// @notice Spec section 30's compare step: does candidateHash match
    /// what's actually on file for certificateId? Returns matches=false
    /// (never a revert) when nothing is registered at all, so callers get
    /// one honest three-state answer - registered-and-matches,
    /// registered-and-mismatches, or never-registered - matching this
    /// project's established "don't conflate not-configured/not-found
    /// with definitely-fake" pattern (see blockchain_service.py).
    function verifyCertificate(
        string calldata certificateId,
        bytes32 candidateHash
    ) external view returns (bool exists, bool matches, bool revoked, uint256 issuedAt, string memory ipfsCid) {
        Certificate[] storage versions = _versions[certificateId];
        if (versions.length == 0) {
            return (false, false, false, 0, "");
        }
        Certificate storage latest = versions[versions.length - 1];
        return (true, latest.certificateHash == candidateHash, latest.revoked, latest.issuedAt, latest.ipfsCid);
    }
}

